head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getFixedColumnLastIndex]<br/>fixedColumn 속성으로 고정되지 않은 Column 중 제일 왼쪽 Column 의 인덱스값를 반환합니다.",
    "validation" : [
        "includeDefaultColumn 파라미터를 true 로 설정 시 rowStatusVisible 과 rowNumVisible 속성에 의해 표시되는 Column 을 인덱스에 포함해야 합니다.",
        "includeDefaultColumn 파라미터를 false 로 설정 시 rowStatusVisible 과 rowNumVisible 속성에 의해 표시되는 Column 을 인덱스에 포함하지 않아야 합니다.",
        "includeDefaultColumn 파라미터 생략 시 기본값 true 로 동작해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        dataList: "data:dlt_bind",
        fixedColumn: 1,
        rowNumVisible: true,
        rowStatusVisible: true,
        rowNumHeaderValue: "No.",
        rowStatusHeaderValue: "St.",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList);

    // 가로 스크롤 생성을 위해 width 변경
    target1.setStyle("width", "250px");
}



scwin.btn_getFixedColumnLastIndex_onclick = function () {
    let includeDefaultColumnText = par_includeDefaultColumn.getText();
    let rtn;

    if (includeDefaultColumnText === '') {
        // 파라미터 생략
        rtn = target1.getFixedColumnLastIndex();
        wf_body_bottom.getObj("scwin").setReturnValue("getFixedColumnLastIndex() : " + rtn);
    } else {
        let includeDefaultColumn = includeDefaultColumnText === 'true';
        rtn = target1.getFixedColumnLastIndex(includeDefaultColumn);
        wf_body_bottom.getObj("scwin").setReturnValue("getFixedColumnLastIndex(" + includeDefaultColumn + ") : " + rtn);
    }
}
